export function reserveStock(sku: string, qty: number): Reservation {
  if (qty <= 0 || !Number.isInteger(qty)) throw new InvalidQuantity(sku, qty);
  const available = ledger.available(sku);
  if (available < qty) throw new OutOfStock(sku, qty, available);
  return ledger.hold(sku, qty, { ttlMinutes: inventoryConfig.reservationTtlMinutes });
}
